join customers c on c.phone = v.phone
where a.customer_id = c.id
  and a.start_time = v.start_time::timestamptz
  and a.status <> 'cancelled'
  and a.created_at is distinct from v.created_at::timestamptz;

select to_char(a.start_time at time zone 'Asia/Taipei', 'MM/DD HH24:MI') as 預約時間, c.name as 客人,
       to_char(a.created_at at time zone 'Asia/Taipei', 'MM/DD HH24:MI') as 建立時間
from appointments a join customers c on c.id = a.customer_id
where a.status <> 'cancelled' and a.start_time >= '2026-10-17T00:00:00+08:00'
order by a.start_time, a.created_at;
